const SEPARATOR = '--- DOCUMENT SEPARATOR ---';
const MAX_CHUNK_SIZE = $("AI Constants").first().json.MAX_CHUNK_SIZE;

let chunks = [];
let startIndex = 0;
let chunkIndex = 0;

function addChunkToArray(chunkText, index) {
  const trimmed = chunkText.trim();
  if (trimmed.length === 0) return;
  chunks.push({
    json: {
      chunkIndex: index + 1,
      // totalChunks буде встановлено після розбиття
      chunkContent: trimmed,
      estimatedTokens: Math.ceil(trimmed.length / 4)
    }
  });
}

while (startIndex < allContent.length) {
  let endIndex = Math.min(startIndex + MAX_CHUNK_SIZE, allContent.length);

  // Якщо є розділювачі — розумне відсікання по SEPARATOR
  if (endIndex < allContent.length) {
    const separatorIndex = allContent.lastIndexOf(SEPARATOR, endIndex);
    // якщо знайшли розділювач в межах поточного блоку (після startIndex)
    if (separatorIndex > startIndex) {
      endIndex = separatorIndex + SEPARATOR.length;
    }
  }

  const chunkText = allContent.slice(startIndex, endIndex);
  addChunkToArray(chunkText, chunkIndex);

  startIndex = endIndex;
  chunkIndex++;
}

// Тепер, коли всі chunks зібрані, встановлюємо totalChunks у кожен елемент
const totalChunks = chunks.length;
const result = chunks.map(item => {
